// Nodes: UC-ORDER-CANCEL-001 SC-001, SC-002, SC-003 (integration = every scenario).
// Steps come from walking each scenario's path. Do not add steps or checks the IR does
// not have; change the IR and regenerate instead.
import { expect, test } from "@playwright/test";
import { fakeBackend } from "./harness.ts";
import { orderDriver } from "./order-driver.playwright.ts";

const UC = "UC-ORDER-CANCEL-001";
const ORDER_ID = "order-1";
// Printed right after the assert of a transition outcome passes (docs/trace.md)
const outcome = (node: string) => console.log(`[ESDD-OUTCOME] ${UC}__${node}`);

test(`${UC}__SC-001 an order progresses to delivered`, async ({ page }) => {
  // given: one paid order exists
  const fake = await fakeBackend(page);
  fake.setOrder({ id: ORDER_ID, status: "PLACED" });
  const order = orderDriver(page);
  await order.open(ORDER_ID, "staff");

  // pack (staff): PLACED → PACKED
  fake.respond("pack", { status: "PACKED" });
  await order.expectStatusNot("status_packed");
  await order.pack();
  await order.expectStatus("status_packed");
  outcome("T-PLACED-pack-o1");
  expect(fake.calls("pack")).toHaveLength(1);

  // hand_over (staff): PACKED → HANDED_OVER
  fake.respond("hand_over", { status: "HANDED_OVER" });
  await order.expectStatusNot("status_shipped");
  await order.handOver();
  await order.expectStatus("status_shipped");
  outcome("T-PACKED-hand_over-o1");
  expect(fake.calls("hand_over")).toHaveLength(1);

  // complete (system): HANDED_OVER → COMPLETED
  await order.expectStatusNot("status_delivered");
  fake.setOrder({ id: ORDER_ID, status: "COMPLETED" });
  await order.refresh();
  await order.expectStatus("status_delivered");
  outcome("T-HANDED_OVER-complete-o1");
});

test(`${UC}__SC-002 cancellation before packing completes free of charge`, async ({ page }) => {
  // given: one paid order exists
  const fake = await fakeBackend(page);
  fake.setOrder({ id: ORDER_ID, status: "PLACED" });
  const order = orderDriver(page);
  await order.open(ORDER_ID, "customer");

  // cancel (customer): PLACED → CANCELED
  fake.respond("cancel", { status: "CANCELED" });
  await order.expectStatusNot("status_canceled");
  await order.cancel();
  await order.expectStatus("status_canceled");
  outcome("T-PLACED-cancel-o1");
  expect(fake.calls("cancel")).toHaveLength(1);
  // T-PLACED-cancel-o2 "no cancellation fee is charged" is not asserted: the IR names no
  // observable for it (question list, order-cancel.tests.yaml), so its node stays uncovered.
});

test(`${UC}__SC-003 cancellation after packing completes with a fee notice`, async ({ page }) => {
  // given: one packed order exists — the path starts at PLACED, so pack is walked first
  // (question list, order-cancel.tests.yaml)
  const fake = await fakeBackend(page);
  fake.setOrder({ id: ORDER_ID, status: "PLACED" });
  const order = orderDriver(page);
  await order.open(ORDER_ID, "staff");

  // pack (staff): PLACED → PACKED
  fake.respond("pack", { status: "PACKED" });
  await order.expectStatusNot("status_packed");
  await order.pack();
  await order.expectStatus("status_packed");
  outcome("T-PLACED-pack-o1");
  expect(fake.calls("pack")).toHaveLength(1);

  // cancel (customer): PACKED → CANCELED
  await order.open(ORDER_ID, "customer");
  fake.respond("cancel", { status: "CANCELED" });
  await order.expectStatusNot("status_canceled");
  await order.expectNoFeeNotice();
  await order.cancel();
  await order.expectStatus("status_canceled");
  outcome("T-PACKED-cancel-o1");
  await order.expectFeeNotice();
  outcome("T-PACKED-cancel-o2");
  expect(fake.calls("cancel")).toHaveLength(1);
});
